1	import jsPDF, { GState } from 'jspdf';
2	import autoTable from 'jspdf-autotable';
3	import { format } from 'date-fns';
4	import { ptBR } from 'date-fns/locale';
5	
6	/**
7	 * Gerador de Relatório PDF de Produção Diária.
8	 *
9	 * Relatório de alto nível: totais por produto, consolidado de TODAS as lojas.
10	 * Segue o padrão visual world-class do Cofre/DRE: border Momma green dupla,
11	 * logo header, watermark central, header/footer por página com paginação,
12	 * resumo executivo e tabela analítica paginada.
13	 *
14	 * O helper `aggregateProducao` é PURO (sem jsPDF) e testável isoladamente.
15	 */
16	
17	// ───────────────────────── TIPOS PÚBLICOS ─────────────────────────
18	
19	export interface ProducaoEntry {
20	  date: string;
21	  product_name: string;
22	  quantity: number;
23	}
24	
25	export interface ProducaoAggregate {
26	  totalQuantity: number;
27	  /** Nº de produtos distintos (por nome). */
28	  distinctProducts: number;
29	  /** Nº de datas distintas com produção. */
30	  activeDays: number;
31	  /** totalQuantity / activeDays (0 se activeDays = 0). */
32	  avgPerDay: number;
33	  /** Ordenado por quantity desc, depois nome asc. */
34	  byProduct: Array<{ product_name: string; quantity: number }>;
35	}
36	
37	export interface GenerateProducaoDiariaPdfParams {
38	  entries: ProducaoEntry[];
39	  dateStart: string; // yyyy-MM-dd
40	  dateEnd: string; // yyyy-MM-dd
41	}
42	
43	// ───────────────────────── HELPER PURO (TESTÁVEL) ─────────────────────────
44	
45	/**
46	 * Agrega lançamentos de produção em totais de alto nível.
47	 *
48	 * - Produtos com mesmo nome têm suas quantidades somadas.
49	 * - Dias são contados por datas distintas (mesma data conta 1).
50	 * - Lista vazia retorna tudo zerado e arrays vazios.
51	 */
52	export function aggregateProducao(entries: ProducaoEntry[]): ProducaoAggregate {
53	  const productTotals = new Map<string, number>();
54	  const distinctDates = new Set<string>();
55	  let totalQuantity = 0;
56	
57	  for (const entry of entries) {
58	    const quantity = Number(entry.quantity) || 0;
59	    totalQuantity += quantity;
60	
61	    const productKey = entry.product_name;
62	    productTotals.set(productKey, (productTotals.get(productKey) ?? 0) + quantity);
63	
64	    if (entry.date) {
65	      distinctDates.add(entry.date);
66	    }
67	  }
68	
69	  const activeDays = distinctDates.size;
70	
71	  const byProduct = Array.from(productTotals.entries())
72	    .map(([product_name, quantity]) => ({ product_name, quantity }))
73	    .sort((a, b) => {
74	      if (b.quantity !== a.quantity) return b.quantity - a.quantity;
75	      return a.product_name.localeCompare(b.product_name, 'pt-BR');
76	    });
77	
78	  return {
79	    totalQuantity,
80	    distinctProducts: productTotals.size,
81	    activeDays,
82	    avgPerDay: activeDays === 0 ? 0 : totalQuantity / activeDays,
83	    byProduct,
84	  };
85	}
86	
87	// ───────────────────────── HELPERS LOCAIS DE PDF ─────────────────────────
88	// Replicados (não importados de outra feature) para respeitar boundaries FSD.
89	
90	const MOMMA_GREEN: [number, number, number] = [87, 113, 91];
91	const MOMMA_GREEN_DARK: [number, number, number] = [30, 37, 31];
92	const MOMMA_GREEN_SOFT: [number, number, number] = [74, 85, 76];
93	
94	/**
95	 * Quantidades podem ser fracionárias (ex.: 0.5). Mostra até 2 casas decimais,
96	 * suprimindo zeros à direita (inteiros ficam sem casas).
97	 */
98	const numberFmt = (v: number): string =>
99	  v.toLocaleString('pt-BR', { minimumFractionDigits: 0, maximumFractionDigits: 2 });
100	
101	const avgFmt = (v: number): string =>
102	  v.toLocaleString('pt-BR', { minimumFractionDigits: 1, maximumFractionDigits: 1 });
103	
104	const loadImage = (url: string): Promise<HTMLImageElement> =>
105	  new Promise((resolve, reject) => {
106	    const img = new Image();
107	    img.crossOrigin = 'Anonymous';
108	    img.onload = () => resolve(img);
109	    img.onerror = () => reject(new Error(`Failed to load image: ${url}`));
110	    img.src = url;
111	  });
112	
113	// ───────────────────────── GERADOR DE PDF ─────────────────────────
114	
115	export async function generateProducaoDiariaPdf(
116	  params: GenerateProducaoDiariaPdfParams,
117	): Promise<void> {
118	  const { entries, dateStart, dateEnd } = params;
119	  const agg = aggregateProducao(entries);
120	
121	  const logoHeader = await loadImage('/logo sistema/01. Reduzida 5.png').catch(
122	    () => null,
123	  );
124	  const watermarkLogo = await loadImage(
125	    '/logo sistema/android-chrome-512x512.png',
126	  ).catch(() => null);
127	
128	  const doc = new jsPDF('p', 'mm', 'a4');
129	  const pageWidth = doc.internal.pageSize.getWidth();
130	  const pageHeight = doc.internal.pageSize.getHeight();
131	
132	  const periodoLabel = `${format(
133	    new Date(dateStart + 'T12:00:00'),
134	    'dd/MM/yyyy',
135	    { locale: ptBR },
136	  )} a ${format(new Date(dateEnd + 'T12:00:00'), 'dd/MM/yyyy', { locale: ptBR })}`;
137	
138	  // ───────────────────────── HEADER, FOOTER & WATERMARK POR PÁGINA ─────────────────────────
139	  const drawPageExtras = (hookData: { pageNumber?: number }) => {
140	    const currentPage = hookData.pageNumber || 1;
141	
142	    // Bordas premium (dupla linha)
143	    doc.setDrawColor(...MOMMA_GREEN);
144	    doc.setLineWidth(0.5);
145	    doc.roundedRect(10, 10, pageWidth - 20, pageHeight - 20, 2, 2, 'S');
146	    doc.setLineWidth(0.2);
147	    doc.roundedRect(12, 12, pageWidth - 24, pageHeight - 24, 2, 2, 'S');
148	
149	    // Logo cabeçalho — preserva aspect ratio
150	    if (logoHeader) {
151	      const ratio = logoHeader.height / logoHeader.width;
152	      let expectedWidth = 45;
153	      let expectedHeight = expectedWidth * ratio;
154	      if (expectedHeight > 18) {
155	        expectedHeight = 18;
156	        expectedWidth = expectedHeight / ratio;
157	      }
158	      doc.addImage(logoHeader, 'PNG', 15, 15, expectedWidth, expectedHeight);
159	    }
160	
161	    // Título e subtítulo (alinhados à direita)
162	    doc.setFont('helvetica', 'bold');
163	    doc.setTextColor(...MOMMA_GREEN_DARK);
164	    doc.setFontSize(16);
165	    doc.text('RELATÓRIO DE PRODUÇÃO DIÁRIA', pageWidth - 15, 20, { align: 'right' });
166	
167	    doc.setFont('helvetica', 'normal');
168	    doc.setFontSize(9);
169	    doc.setTextColor(...MOMMA_GREEN);
170	    doc.text('TOTAIS POR PRODUTO — CONSOLIDADO', pageWidth - 15, 25, {
171	      align: 'right',
172	    });
173	
174	    doc.setTextColor(...MOMMA_GREEN_SOFT);
175	    doc.setFontSize(8);
176	    doc.text(`Período: ${periodoLabel}`, pageWidth - 15, 31, { align: 'right' });
177	    doc.text('Unidade: Todas as lojas', pageWidth - 15, 35, { align: 'right' });
178	
179	    // Linha separadora abaixo do header
180	    doc.setDrawColor(...MOMMA_GREEN);
181	    doc.setLineWidth(0.5);
182	    doc.line(15, 43, pageWidth - 15, 43);
183	
184	    // Footer com paginação
185	    doc.setFont('helvetica', 'normal');
186	    doc.setFontSize(8);
187	    doc.setTextColor(...MOMMA_GREEN);
188	    const totalPages = doc.getNumberOfPages();
189	    doc.text(
190	      `Relatório de Produção Momma • Emissão: ${format(new Date(), "dd/MM/yyyy 'às' HH:mm", { locale: ptBR })} • Pág. ${currentPage}/${totalPages}`,
191	      pageWidth / 2,
192	      pageHeight - 12,
193	      { align: 'center' },
194	    );
195	
196	    // Watermark sutil ao centro
197	    if (watermarkLogo) {
198	      try {
199	        doc.setGState(new GState({ opacity: 0.08 }));
200	        const wSize = 200;
201	        doc.addImage(
202	          watermarkLogo,
203	          'PNG',
204	          (pageWidth - wSize) / 2,
205	          (pageHeight - wSize) / 2,
206	          wSize,
207	          wSize,
208	        );
209	        doc.setGState(new GState({ opacity: 1.0 }));
210	      } catch {
211	        /* fallback silencioso */
212	      }
213	    }
214	  };
215	
216	  // Página 1: header desenhado manualmente (resumo é desenhado fora do autoTable)
217	  drawPageExtras({ pageNumber: 1 });
218	
219	  // ───────────────────────── RESUMO EXECUTIVO ─────────────────────────
220	  let cursorY = 52;
221	
222	  doc.setFont('helvetica', 'bold');
223	  doc.setFontSize(11);
224	  doc.setTextColor(...MOMMA_GREEN);
225	  doc.text('RESUMO EXECUTIVO DO PERÍODO', 15, cursorY);
226	  cursorY += 5;
227	
228	  const boxX = 15;
229	  const boxW = pageWidth - 30;
230	  const boxH = 22;
231	
232	  doc.setFillColor(248, 250, 248);
233	  doc.setDrawColor(...MOMMA_GREEN);
234	  doc.setLineWidth(0.4);
235	  doc.roundedRect(boxX, cursorY, boxW, boxH, 2, 2, 'FD');
236	
237	  const colW = boxW / 4;
238	  const drawMetric = (
239	    label: string,
240	    value: string,
241	    colIndex: number,
242	    valueFontSize: number,
243	  ) => {
244	    doc.setFont('helvetica', 'normal');
245	    doc.setFontSize(8);
246	    doc.setTextColor(120, 120, 120);
247	    doc.text(label, boxX + colW * colIndex + 4, cursorY + 6);
248	    doc.setFont('helvetica', 'bold');
249	    doc.setFontSize(valueFontSize);
250	    doc.setTextColor(...MOMMA_GREEN_DARK);
251	    doc.text(value, boxX + colW * colIndex + 4, cursorY + 14);
252	  };
253	
254	  drawMetric('TOTAL PRODUZIDO', numberFmt(agg.totalQuantity), 0, 13);
255	  drawMetric('PRODUTOS DISTINTOS', numberFmt(agg.distinctProducts), 1, 13);
256	  drawMetric('DIAS COM PRODUÇÃO', numberFmt(agg.activeDays), 2, 13);
257	  drawMetric('MÉDIA / DIA', avgFmt(agg.avgPerDay), 3, 13);
258	
259	  cursorY += boxH + 8;
260	
261	  // ───────────────────────── TABELA: PRODUÇÃO POR PRODUTO ─────────────────────────
262	  doc.setFont('helvetica', 'bold');
263	  doc.setFontSize(11);
264	  doc.setTextColor(...MOMMA_GREEN);
265	  doc.text('PRODUÇÃO POR PRODUTO', 15, cursorY);
266	  cursorY += 3;
267	
268	  const productBody = agg.byProduct.map((p) => [p.product_name, numberFmt(p.quantity)]);
269	  productBody.push(['TOTAL GERAL', numberFmt(agg.totalQuantity)]);
270	
271	  autoTable(doc, {
272	    startY: cursorY,
273	    head: [['Produto', 'Quantidade']],
274	    body: productBody,
275	    theme: 'plain',
276	    styles: {
277	      fontSize: 8,
278	      font: 'helvetica',
279	      cellPadding: { top: 1.8, bottom: 1.8, left: 2, right: 2 },
280	      textColor: [60, 60, 60],
281	      lineColor: [230, 230, 230],
282	      lineWidth: { bottom: 0.1 },
283	    },
284	    headStyles: {
285	      fillColor: MOMMA_GREEN,
286	      textColor: [255, 255, 255],
287	      fontStyle: 'bold',
288	      fontSize: 8.5,
289	      cellPadding: { top: 2.5, bottom: 2.5, left: 2, right: 2 },
290	      lineWidth: 0,
291	    },
292	    alternateRowStyles: { fillColor: [248, 250, 248] },
293	    columnStyles: {
294	      0: { cellWidth: 'auto' },
295	      1: { cellWidth: 35, halign: 'right', fontStyle: 'bold' },
296	    },
297	    didParseCell: (data) => {
298	      // Última linha = Total Geral em destaque
299	      if (data.section === 'body' && data.row.index === productBody.length - 1) {
300	        data.cell.styles.fontStyle = 'bold';
301	        data.cell.styles.fillColor = [236, 242, 237];
302	        data.cell.styles.textColor = MOMMA_GREEN_DARK;
303	      }
304	    },
305	    didDrawPage: (hk) => {
306	      if (hk.pageNumber > 1) {
307	        drawPageExtras(hk);
308	      }
309	    },
310	    margin: { top: 50, left: 15, right: 15, bottom: 20 },
311	  });
312	
313	  // ───────────────────────── PERSISTÊNCIA ─────────────────────────
314	  doc.save(`producao-diaria_${dateStart}_a_${dateEnd}.pdf`);
315	}
