115	export function LossAnalyticsDashboard({ losses, users, stores }: LossAnalyticsDashboardProps) {
116	    const today = new Date();
117	    // Default to strict 'today' month start to avoid day drift issues
118	    const defaultStart = startOfMonth(today);
119	
120	    // State for Date Range Filter
121	    const [dateRange, setDateRange] = useState<DateRange | undefined>({
122	        from: defaultStart,
123	        to: today
124	    });
125	
126	    const [selectedMetric, setSelectedMetric] = useState<string | null>(null);
127	    const [searchTerm, setSearchTerm] = useState("");
128	
129	    // Advanced Filters State
130	    const [selectedStore, setSelectedStore] = useState<string>("all");
131	    const [selectedReason, setSelectedReason] = useState<string>("all");
132	    const [productFilter, setProductFilter] = useState<string>("");
133	
134	    // Report Dialog State
135	    const [reportOpen, setReportOpen] = useState(false);
136	    const [reportReasons, setReportReasons] = useState<Set<string>>(new Set());
137	    const [reportColumns, setReportColumns] = useState<Set<string>>(new Set([
138	        'data', 'loja', 'produto', 'quantidade', 'unidade', 'preco_unit', 'valor_total', 'motivo', 'responsavel'
139	    ]));
140	
141	    // Extract unique reasons for filter
142	    const uniqueReasons = useMemo(() => {
143	        const reasons = new Set(losses.map(l => l.motivo_perda).filter(Boolean));
144	        return Array.from(reasons).sort();
145	    }, [losses]);
146	
147	    const openReportDialog = () => {
148	        setReportReasons(new Set(uniqueReasons));
149	        setReportOpen(true);
150	    };
151	
152	    const toggleReportReason = (reason: string) => {
153	        setReportReasons(prev => {
154	            const next = new Set(prev);
155	            if (next.has(reason)) next.delete(reason);
156	            else next.add(reason);
157	            return next;
158	        });
159	    };
160	
161	    const toggleReportColumn = (col: string) => {
162	        setReportColumns(prev => {
163	            const next = new Set(prev);
164	            if (next.has(col)) next.delete(col);
165	            else next.add(col);
166	            return next;
167	        });
168	    };
169	
170	    const REPORT_COLUMN_OPTIONS = [
171	        { key: 'data', label: 'Data' },
172	        { key: 'loja', label: 'Loja' },
173	        { key: 'produto', label: 'Produto' },
174	        { key: 'quantidade', label: 'Quantidade' },
175	        { key: 'unidade', label: 'Unidade' },
176	        { key: 'preco_unit', label: 'Preço Unitário' },
177	        { key: 'valor_total', label: 'Valor Total' },
178	        { key: 'motivo', label: 'Motivo da Perda' },
179	        { key: 'responsavel', label: 'Responsável' },
180	        { key: 'lote', label: 'Lote' },
181	        { key: 'observacoes', label: 'Observações' },
182	    ];
183	
184	    // --- Filter Logic ---
185	    const filteredLosses = useMemo(() => {
186	        if (!dateRange?.from) return losses;
187	
188	        return losses.filter(l => {
189	            // 1. Date Filter
190	            if (!l.data_identificacao) return false;
191	            const date = parseISO(l.data_identificacao);
192	            if (!isValid(date)) return false;
193	
194	            const from = dateRange.from as Date;
195	            const to = dateRange.to || dateRange.from || new Date();
196	
197	            const target = date.getTime();
198	            const startStr = new Date(from).setHours(0, 0, 0, 0);
199	            const endStr = new Date(to).setHours(23, 59, 59, 999);
200	
201	            if (target < startStr || target > endStr) return false;
202	
203	            // 2. Store Filter
204	            if (selectedStore !== "all" && String(l.loja_id) !== selectedStore) return false;
205	
206	            // 3. Reason Filter
207	            if (selectedReason !== "all" && l.motivo_perda !== selectedReason) return false;
208	
209	            // 4. Product Filter
210	            if (productFilter && !((l.produto_nome_perda || "").toLowerCase().includes(productFilter.toLowerCase()))) return false;
211	
212	            return true;
213	        });
214	    }, [losses, dateRange, selectedStore, selectedReason, productFilter]);
215	
216	    // --- Analytics Logic ---
217	    const analytics = useMemo(() => {
218	        const totalRecords = filteredLosses.length;
219	        const totalQuantity = filteredLosses.reduce((acc, curr) => acc + (Number(curr.quantidade) || 0), 0);
220	        const totalValue = filteredLosses.reduce((acc, curr) => acc + (Number(curr.valor_estimado) || 0), 0);
221	
222	        // Daily Averages
223	        const daysDiff = dateRange?.from && dateRange?.to
224	            ? Math.max(1, differenceInDays(dateRange.to, dateRange.from) + 1) // +1 to include both start and end dates
225	            : 30;
226	
227	        const avgDailyQty = totalQuantity / daysDiff;
228	        const avgDailyVal = totalValue / daysDiff;
229	
230	        // Grouping Logic (Dynamic: Day if < 60 days, Month otherwise)
231	        const isDailyGroup = daysDiff < 60;
232	
233	        const byHour: Record<number, number> = {};
234	        const byUser: Record<number, number> = {};
235	        const byStore: Record<string, number> = {};         // Qty
236	        const byStoreValue: Record<string, number> = {};    // Value
237	        const byProduct: Record<string, number> = {};       // Qty
238	        const byProductValue: Record<string, number> = {};  // Value
239	        const byTime: Record<string, { date: string; quantity: number; value: number; logs: number }> = {};
240	        const storeByTimeRaw: Record<string, any> = {};
241	
242	        // Detailed List for Modal/Table
243	        const detailedList = [...filteredLosses].map(l => ({
244	            ...l,
245	            val: Number(l.valor_estimado) || 0,
246	            qty: Number(l.quantidade) || 0,
247	            prod: l.produto_nome_perda || "Desconhecido",
248	            store: l.stores?.nome || "Outra",
249	            date: l.data_identificacao
250	        })).sort((a, b) => b.val - a.val);
251	
252	        filteredLosses.forEach(l => {
253	            const date = l.data_identificacao ? parseISO(l.data_identificacao) : new Date();
254	            const hour = getHours(date);
255	
256	            // Dynamic Key
257	            const timeKey = isDailyGroup ? format(date, "yyyy-MM-dd") : format(date, "yyyy-MM");
258	            const timeLabel = isDailyGroup ? format(date, "dd/MM") : format(date, "MMM/yy", { locale: ptBR });
259	
