const toggleReportColumn = (col: string) => {
    setReportColumns(prev => {
        const next = new Set(prev);
        if (next.has(col)) next.delete(col);
        else next.add(col);
        return next;
    });
};

const REPORT_COLUMN_OPTIONS = [
    { key: 'data', label: 'Data' },
    { key: 'loja', label: 'Loja' },
    { key: 'produto', label: 'Produto' },
    { key: 'quantidade', label: 'Quantidade' },
    { key: 'unidade', label: 'Unidade' },
    { key: 'preco_unit', label: 'Preço Unitário' },
    { key: 'valor_total', label: 'Valor Total' },
    { key: 'motivo', label: 'Motivo da Perda' },
    { key: 'responsavel', label: 'Responsável' },
    { key: 'lote', label: 'Lote' },
    { key: 'observacoes', label: 'Observações' },
];

// --- Filter Logic ---

// --- Report Generation ---
const handleGenerateReport = () => {
    if (reportReasons.size === 0) {
        toast.error("Selecione ao menos um motivo de perda.");
        return;
    }
    if (reportColumns.size === 0) {
        toast.error("Selecione ao menos uma coluna para o relatório.");
        return;
    }

    // Filter by selected reasons
    const reportData = analytics.detailedList.filter(item => reportReasons.has(item.motivo_perda));

    if (!reportData.length) {
        toast.error("Sem dados para os motivos selecionados.");
        return;
    }

    // Build header and rows based on selected columns
    const columnMap: Record<string, { header: string; getValue: (item: any) => string }> = {
        data: { header: 'Data', getValue: (item) => item.date ? format(parseISO(item.date), "dd/MM/yyyy HH:mm") : "-" },
        loja: { header: 'Loja', getValue: (item) => item.store },
        produto: { header: 'Produto', getValue: (item) => item.prod },
        quantidade: { header: 'Quantidade', getValue: (item) => Number(item.qty).toFixed(3) },
        unidade: { header: 'Unidade', getValue: (item) => item.unidade || "uni" },
        preco_unit: { header: 'Preço Unit. (R$)', getValue: (item) => Number(item.preco_unitario || 0).toFixed(2) },
        valor_total: { header: 'Valor Total (R$)', getValue: (item) => Number(item.val).toFixed(2) },
        motivo: { header: 'Motivo', getValue: (item) => item.motivo_perda },
        responsavel: { header: 'Responsável', getValue: (item) => users.find(u => u.id === item.responsavel_id)?.nome || "Sistema" },
        lote: { header: 'Lote', getValue: (item) => item.lote || "-" },
        observacoes: { header: 'Observações', getValue: (item) => item.observacoes || "-" },
    };

    const selectedCols = REPORT_COLUMN_OPTIONS.filter(c => reportColumns.has(c.key));
    const header = selectedCols.map(c => columnMap[c.key].header);
    const rows = reportData.map(item => selectedCols.map(c => columnMap[c.key].getValue(item)));

    // Summary calculations
    const totalValue = reportData.reduce((s, i) => s + Number(i.val), 0);
    const totalQty = reportData.reduce((s, i) => s + Number(i.qty), 0);
    const daysDiff = dateRange?.from && dateRange?.to
        ? Math.max(1, differenceInDays(dateRange.to, dateRange.from) + 1)
        : 30;

    // Breakdown by reason
    const byReason: Record<string, { count: number; value: number }> = {};
    reportData.forEach(item => {
        const r = item.motivo_perda;
        if (!byReason[r]) byReason[r] = { count: 0, value: 0 };
        byReason[r].count++;
        byReason[r].value += Number(item.val);
    });

    const periodLabel = dateRange?.from
        ? `${format(dateRange.from, 'dd/MM/yyyy')} - ${format(dateRange.to || new Date(), 'dd/MM/yyyy')}`
        : "Total";

    const summaryRows: any[][] = [
        ["Relatório de Perdas - Momma Doces"],
        ["Período", periodLabel],
        ["Motivos Incluídos", Array.from(reportReasons).join(", ")],
        [""],
        ["Total Valor (R$)", totalValue.toFixed(2)],
        ["Total Quantidade", totalQty.toFixed(3)],
        ["Média Diária (R$)", (totalValue / daysDiff).toFixed(2)],
        ["Média Diária (Qtd)", (totalQty / daysDiff).toFixed(3)],
        ["Total Registros", reportData.length],
        [""],
        ["Detalhamento por Motivo"],
        ["Motivo", "Registros", "Valor (R$)"],
        ...Object.entries(byReason)
            .sort((a, b) => b[1].value - a[1].value)
            .map(([name, data]) => [name, data.count, data.value.toFixed(2)]),
    ];

    const wb = XLSX.utils.book_new();
    const wsSummary = XLSX.utils.aoa_to_sheet(summaryRows);
    const wsDetail = XLSX.utils.aoa_to_sheet([header, ...rows]);
    XLSX.utils.book_append_sheet(wb, wsSummary, "Resumo");
    XLSX.utils.book_append_sheet(wb, wsDetail, "Detalhado");

    XLSX.writeFile(wb, `Relatorio_Perdas_Momma_${format(new Date(), 'yyyyMMdd_HHmm')}.xlsx`);
    toast.success(`Relatório gerado com ${reportData.length} registros!`);
    setReportOpen(false);
};

